    pot+=g; kin+=g*Math.sqrt((Math.cos(t*fx+px)*rx*fx)**2+(Math.sin(t*fy+py)*ry*fy)**2)*0.25;
    rip+=Math.sin(d*0.09-t*1.8*m*0.4)*g*2.5;
