  const diff=(Math.sin(sx*0.05+sy*0.03+t*0.9)+Math.sin(sx*0.03-sy*0.05+t*1.3))*0.3+
    Math.sin((sx+sy)*0.08+t*2.8)*0.15+Math.sin((sx-sy)*0.07-t*2.2)*0.15;
